async function api(path,method='GET',body,meta=false){
 const generation=state.authGeneration||0,accessContext=state.me?.access_context;
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);let response;try{response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:controller.signal})}catch(e){clearTimeout(timeout);throw Error(e.name==='AbortError'?'请求超时，请检查网络后重试':'暂时无法连接服务器，请检查网络后重试')}
 let data;try{data=await response.json()}catch(e){throw Error(e.name==='AbortError'?'读取响应超时，请检查网络后重试':`服务器返回了非预期页面（HTTP ${response.status}），请检查站点配置`)}finally{clearTimeout(timeout)}
 if(generation!==(state.authGeneration||0)){const stale=Error('Account changed; old response discarded');stale.stale=true;throw stale}
 const responseContext=response.headers.get('X-Access-Context');if(path!=='me'&&path!=='login'&&accessContext&&responseContext&&accessContext!==responseContext){showLogin();setTimeout(()=>start().catch(showError),0);const stale=Error('Account context changed');stale.stale=true;throw stale}
 if(response.status===401){showLogin();throw Error(path==='login'?'账户或密码不正确':'登录已过期，请重新登录')}
 if(!response.ok){const error=Error(typeof data.detail==='string'?data.detail:'提交失败，请检查填写内容');error.updating=response.status===503&&data.updating===true;throw error}
 return meta?{data,total:response.headers.has('X-Total-Count')?Number(response.headers.get('X-Total-Count')):null}:data;
}
function badge(text,tone='off'){return node('span',text,'badge '+tone)}
function platformBadges(value){const group=node('span',undefined,'platform-badges');const tags=normalizePlatforms(value);if(Array.isArray(value))for(const key of value)if(typeof key==='string'&&/^[a-z][a-z0-9_-]{0,15}$/.test(key)&&!tags.includes(key))tags.push(key);for(const key of tags){const p=platformOptions.find(p=>p.value===key),tag=node('span',undefined,'platform-tag platform-'+key);const mark=node('span',undefined,'platform-glyph');mark.setAttribute('aria-hidden','true');if(platformMarks[key])mark.innerHTML=platformMarks[key];else {mark.style.fontSize='11px';mark.textContent=p?.glyph||key.slice(0,1);mark.style.background='transparent';}tag.append(mark,node('span',p?.label||key));group.append(tag)}if(!tags.length)group.append(node('span','未设置平台','platform-unknown'));return group}
