function syncSummary(partial=0){if(!can('devices.view'))return `${partial?'部分更新':'后台已读取'} ${new Date().toLocaleTimeString('zh-CN',{hour12:false})} · 仅显示授权数据`;const times=state.devices.map(d=>Number(d.heartbeat||0)),last=Math.max(0,...times);return `${partial?'部分更新':'后台已读取'} ${new Date().toLocaleTimeString('zh-CN',{hour12:false})} · 手机最新上报 ${last?fullTime(last):'暂无'}${state.refreshBatch?' · '+refreshCounts():''}`}
function feedbackNow(){const b=state.refreshBatch;return b?.server_at?Number(b.server_at)+Math.max(0,performance.now()-(b.sampled_at_ms??performance.now()))/1000:Date.now()/1000}
