// The update screen owns its requests and timer; ordinary dashboard refreshes do not poll it.
function stopUpdateWork(){clearTimeout(updateTimer);updateEpoch++;updateXHR?.abort();updateXHR=null;updateRequest=null;state.updateBusy=false;}
function updateContext(){const generation=state.authGeneration||0,epoch=updateEpoch,context=state.me?.access_context;return ()=>generation===(state.authGeneration||0)&&epoch===updateEpoch&&context===state.me?.access_context&&state.me?.role==='admin'&&state.tab==='updates';}
function updateRunning(){return ['queued','running'].includes(state.updates?.job?.status);}
function paintUpdates(){if(state.me?.role==='admin'&&state.tab==='updates'){$('#content').replaceChildren(...updatesView());$('#refresh').disabled=!!state.updateBusy;$('#refresh').lastChild.textContent='检查更新状态';}}
async function loadUpdates(){
 if(state.me?.role!=='admin'||state.tab!=='updates')return;
 if(updateRequest)return updateRequest;
 clearTimeout(updateTimer);const valid=updateContext();
 const request=(async()=>{try{const data=await api('admin/updates/status');if(!valid())return;state.updates=data;state.updateError='';}catch(e){if(!valid()||e.stale)return;state.updateError=e.updating?'正在升级，站点暂时维护中；正在等待升级结果…':e.message;}finally{if(valid()){paintUpdates();if(updateRunning())updateTimer=setTimeout(()=>{if(!state.modal&&!state.updateBusy)loadUpdates();else scheduleUpdatePoll();},2000);}}})();
 updateRequest=request;try{return await request}finally{if(updateRequest===request)updateRequest=null;}
}
function scheduleUpdatePoll(){clearTimeout(updateTimer);if(state.me?.role==='admin'&&state.tab==='updates'&&updateRunning())updateTimer=setTimeout(()=>{if(state.modal||state.updateBusy)scheduleUpdatePoll();else loadUpdates();},2000);}
function uploadUpdate(file,onProgress,url='/api/admin/updates/upload',field='package',extra={}){
 const valid=updateContext();return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();updateXHR=xhr;xhr.open('POST',url);xhr.withCredentials=true;xhr.timeout=180000;xhr.setRequestHeader('X-CSRF-Token',state.csrf);
 const fail=message=>reject(Error(message));xhr.upload.onprogress=e=>{if(valid())onProgress(e.lengthComputable?Math.round(e.loaded/e.total*100):null)};
 xhr.onerror=()=>fail('上传连接中断，请检查网络并重试');xhr.ontimeout=()=>fail('上传超时，请检查网络并重试');xhr.onabort=()=>{const e=Error('上传已取消');e.stale=true;reject(e)};
 xhr.onload=()=>{if(!valid()){const e=Error('账户或页面已切换');e.stale=true;reject(e);return}const context=xhr.getResponseHeader('X-Access-Context');if(context&&state.me.access_context&&context!==state.me.access_context){showLogin();setTimeout(()=>start().catch(showError),0);fail('账户权限已变更，请重新登录');return}if(xhr.status===401){showLogin();fail('登录已过期，请重新登录');return}let data;try{data=JSON.parse(xhr.responseText)}catch{fail(`服务器返回了非预期页面（HTTP ${xhr.status}）`);return}if(xhr.status<200||xhr.status>=300){fail(typeof data.detail==='string'?data.detail:'上传失败，请检查发布包');return}resolve(data);};const form=new FormData();form.append(field,file);for(const [key,value] of Object.entries(extra))form.append(key,value);xhr.send(form);
 });
}
function confirmUpdate(kind){
 const staged=state.updates?.staged;if(!staged||state.updateBusy||updateRunning())return;const valid=updateContext();
 const backend=kind==='apply',box=modal(backend?'确认升级后台':'确认发布 App',backend?`将升级到 ${staged.version}。系统会先自动备份并进入维护模式，期间暂不可操作。请保持页面打开，等待最终结果。`:`将发布 App ${staged.app?.version_name}，手机可检查并由用户确认安装。`);
 const error=node('p',undefined,'form-error');error.setAttribute('role','alert');box.body.append(error);
 const save=button(backend?'备份并开始升级':'发布 App',async()=>{if(!valid()||state.modal!==box.d||!box.d.open)return;save.disabled=true;state.updateBusy=true;try{const result=await api('admin/updates/'+kind,'POST',{id:staged.id});if(!valid())return;if(backend){state.updates.job=result.job||result;state.updateError='升级任务已提交，正在确认执行结果…';}box.close();paintUpdates();await loadUpdates();}catch(e){if(valid()&&box.d.open){error.textContent=e.message;save.disabled=false;}}finally{if(valid()){state.updateBusy=false;paintUpdates();scheduleUpdatePoll();}}},'primary');box.footer.append(button('取消',box.close),save);
}
